/** Shape of openings/openings.json (generated by scripts/generate-openings.ts from lichess-org/chess-openings, CC0). */
export interface OpeningsData {
  /** Distinct opening families (the part of the name before ':'), sorted. */
  readonly families: readonly string[];
  /** Named lines: [eco, full name, family index, plies]. */
  readonly names: readonly (readonly [string, string, number, number])[];
  /** Every position (EPD: first 4 FEN fields) on any named line. */
  readonly positions: Readonly<Record<string, BookNode>>;
}

export interface BookNode {
  /** Index into `names` when this exact position ends a named line (the longest one if several). */
  readonly n?: number;
  /** Book continuations: uci -> { f: family indexes, c: number of named lines that play that move here }. */
  readonly x: Readonly<Record<string, { readonly f: readonly number[]; readonly c: number }>>;
}
